function getExabeamTranslation(key, lang) {
    return (exabeamTranslations[lang] && exabeamTranslations[lang][key]) ||
           (exabeamTranslations.en && exabeamTranslations.en[key]) || null;
}

function applyExabeamTranslations(lang) {
    let count = 0;
    document.querySelectorAll("[data-i18n]").forEach(el => {
        const key = el.getAttribute("data-i18n");
        if (key && (key.startsWith("review.exabeam.") || key.startsWith("review.common."))) {
            const translation = getExabeamTranslation(key, lang);
            if (translation) { el.textContent = translation; count++; }
        }
    });
    
}

window.addEventListener("languageChanged", e => setTimeout(() => applyExabeamTranslations(e.detail.language), 200));

if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", () => applyExabeamTranslations(window.i18n?.getCurrentLanguage() || "en"));
} else {
    applyExabeamTranslations(window.i18n?.getCurrentLanguage() || "en");
}
